15	// serviceSessionLog is the service-owned writer that persists the session
16	// lifecycle records (session.start + session.end) for one Execute call. It
17	// is constructed in runExecute after the route is resolved and torn down in
18	// a defer on the same goroutine. Sub-paths (runNative, runSubprocess, ...)
19	// emit the terminal event through finalizeAndEmit, which delegates here to
20	// keep the session log in sync with the public event stream.
21	type serviceSessionLog struct {
22		logger    *session.Logger
23		path      string
24		sessionID string
25		endOnce   sync.Once
26		endWrote  atomic.Bool
27		closeOnce sync.Once
28	}
29	
30	// openSessionLog creates the session-log writer for req and emits the
31	// session.start record. A nil-or-empty req.SessionLogDir yields a no-op
32	// writer so callers don't need to branch on whether logging is enabled.
33	func (s *service) openSessionLog(req ServiceExecuteRequest, decision RouteDecision, sessionID string) *serviceSessionLog {
34		if req.SessionLogDir == "" || sessionID == "" {
35			return &serviceSessionLog{}
36		}
37		logger := session.NewLogger(req.SessionLogDir, sessionID)
38		sl := &serviceSessionLog{
39			logger:    logger,
40			path:      filepath.Join(req.SessionLogDir, sessionID+".jsonl"),
41			sessionID: sessionID,
42		}
43		start := session.SessionStartData{
44			Provider:          s.providerTypeLabel(decision.Provider),
45			Model:             decision.Model,
46			SelectedProvider:  decision.Provider,
47			SelectedRoute:     req.SelectedRoute,
48			RequestedModel:    req.Model,
49			RequestedModelRef: req.ModelRef,
50			ResolvedModelRef:  req.ResolvedModelRef,
51			ResolvedModel:     decision.Model,
52			Reasoning:         req.Reasoning,
53			WorkDir:           req.WorkDir,
54			MaxIterations:     req.MaxIterations,
55			Prompt:            req.Prompt,
56			SystemPrompt:      req.SystemPrompt,
57			Metadata:          req.Metadata,
58		}
59		logger.Emit(agentcore.EventSessionStart, start)
60		return sl
61	}
62	
63	// writeEnd records the terminal session.end event. It is idempotent: the
64	// first call wins. Callers should invoke this whenever a harnesses.FinalData
65	// is produced — finalizeAndEmit threads it together with the public-stream
66	// emit so the two views stay consistent.
67	func (sl *serviceSessionLog) writeEnd(req ServiceExecuteRequest, meta map[string]string, final harnesses.FinalData) {
68		if sl == nil || sl.logger == nil {
69			return
70		}
71		sl.endOnce.Do(func() {
72			sl.endWrote.Store(true)
73			end := session.SessionEndData{
74				Status:            harnessStatusToCoreStatus(final.Status),
75				Output:            final.FinalText,
76				Tokens:            finalUsageToCoreTokens(final.Usage),
77				DurationMs:        final.DurationMS,
78				SelectedRoute:     req.SelectedRoute,
79				RequestedModel:    req.Model,
80				RequestedModelRef: req.ModelRef,
81				ResolvedModelRef:  req.ResolvedModelRef,
82				Reasoning:         req.Reasoning,
83				Metadata:          meta,
84				Error:             final.Error,
85			}
86			if final.CostUSD > 0 {
87				cost := final.CostUSD
88				end.CostUSD = &cost
89			}
90			if final.RoutingActual != nil {
91				end.Model = final.RoutingActual.Model
92				end.SelectedProvider = final.RoutingActual.Provider
93				end.ResolvedModel = final.RoutingActual.Model
94				end.AttemptedProviders = append([]string(nil), final.RoutingActual.FallbackChainFired...)
95				if len(end.AttemptedProviders) > 1 {
96					end.FailoverCount = len(end.AttemptedProviders) - 1
97				}
98			}
99			sl.logger.Emit(agentcore.EventSessionEnd, end)
100		})
101	}
