103	// writeEvent persists a raw agent event to the session log. Used by the
104	// native loop callback to capture llm.request / llm.response / tool.call /
105	// compaction.* events so kept-sandbox bundles preserve a complete trace
106	// for benchmark reruns and post-mortem debugging. session.start and
107	// session.end are skipped because writeStart/writeEnd own those records and
108	// enrich them with service-side routing fields the loop does not see.
109	func (sl *serviceSessionLog) writeEvent(ev agentcore.Event) {
110		if sl == nil || sl.logger == nil {
111			return
112		}
113		switch ev.Type {
114		case agentcore.EventSessionStart, agentcore.EventSessionEnd,
115			agentcore.EventOverride, agentcore.EventRejectedOverride:
116			return
117		}
118		sl.logger.Write(ev)
119	}
120	
121	// writeOverrideEvent persists an override or rejected_override payload to
122	// the session log so windowed reporting (UsageReport, ADR-006 §5) can
123	// recompute routing-quality across restarts and beyond the in-memory
124	// ring's bounded retention. eventType is one of ServiceEventTypeOverride
125	// / ServiceEventTypeRejectedOverride.
126	func (sl *serviceSessionLog) writeOverrideEvent(eventType string, payload ServiceOverrideData) {
127		if sl == nil || sl.logger == nil {
128			return
129		}
130		raw, err := json.Marshal(payload)
131		if err != nil {
132			return
133		}
134		sl.logger.Write(agentcore.Event{
135			SessionID: sl.sessionID,
136			Type:      agentcore.EventType(eventType),
137			Timestamp: time.Now().UTC(),
138			Data:      raw,
139		})
140	}
