160	// persistRejectedOverride writes a session.start + rejected_override pair
161	// to a freshly-opened session log for sessionID. Used by Execute's
162	// pre-dispatch rejection branch, which never reaches runExecute and so
163	// never goes through the normal openSessionLog path. Without this,
164	// rejected_override events are invisible to UsageReport (which scans
165	// session logs over a --since window).
166	//
167	// The session.start is required by ScanRoutingQuality, which only counts
168	// log files that include one — and we want this rejection counted in
169	// TotalRequests so AutoAcceptanceRate reflects reality.
170	func (s *service) persistRejectedOverride(req ServiceExecuteRequest, sessionID string, payload ServiceOverrideData) {
171		if req.SessionLogDir == "" || sessionID == "" {
172			return
173		}
174		sl := s.openSessionLog(req, RouteDecision{}, sessionID)
175		if sl == nil || sl.logger == nil {
176			return
177		}
178		defer sl.close()
179		sl.writeOverrideEvent(ServiceEventTypeRejectedOverride, payload)
180	}
