182	// providerTypeLabel maps a configured provider name ("local") to its provider
183	// type ("lmstudio") when available. Returns the input unchanged if no
184	// ServiceConfig is attached or the name is not configured. Callers use this
185	// to populate session-log Provider fields, which historically carry the
186	// provider *type* rather than the configured name.
187	func (s *service) providerTypeLabel(name string) string {
188		if s == nil || s.opts.ServiceConfig == nil || name == "" {
189			return name
190		}
191		entry, ok := s.opts.ServiceConfig.Provider(name)
192		if !ok || entry.Type == "" {
193			return name
194		}
195		return entry.Type
196	}
