198	// harnessStatusToCoreStatus maps a public harnesses.FinalData.Status string
199	// to an internal agentcore.Status. Unknown / error-y statuses collapse to
200	// StatusError so session.end always carries a well-defined status.
201	func harnessStatusToCoreStatus(status string) agentcore.Status {
202		switch status {
203		case "success":
204			return agentcore.StatusSuccess
205		case "iteration_limit":
206			return agentcore.StatusIterationLimit
207		case "cancelled":
208			return agentcore.StatusCancelled
209		default:
210			return agentcore.StatusError
211		}
212	}
