214	// finalUsageToCoreTokens converts the public FinalUsage pointer form into
215	// the internal TokenUsage struct used by session.end. Nil usage yields a
216	// zero-value struct.
217	func finalUsageToCoreTokens(usage *harnesses.FinalUsage) agentcore.TokenUsage {
218		if usage == nil {
219			return agentcore.TokenUsage{}
220		}
221		return agentcore.TokenUsage{
222			Input:      derefHarnessInt(usage.InputTokens),
223			Output:     derefHarnessInt(usage.OutputTokens),
224			CacheRead:  derefHarnessInt(usage.CacheReadTokens),
225			CacheWrite: derefHarnessInt(usage.CacheWriteTokens),
226			Total:      derefHarnessInt(usage.TotalTokens),
227		}
228	}
229	
230	func derefHarnessInt(v *int) int {
231		if v == nil {
232			return 0
233		}
234		return *v
235	}
